import { createHash, randomUUID } from 'crypto';
import fs from 'fs/promises';
import path from 'path';
const digest = (text: string): string =>
  createHash('sha256').update(text).digest('hex');
const ensureDirectory = async (directory: string): Promise<void> => {
  await fs.mkdir(directory).catch((error: NodeJS.ErrnoException) => {
    if (error.code !== 'EEXIST') throw error;
  });
  const stat = await fs.lstat(directory);
  if (!stat.isDirectory() || stat.isSymbolicLink())
    throw new Error(`Reference directory is not safe: ${directory}`);
};

const validateTree = async (
  root: string,
  files: Array<{ name: string; content: string }>,
): Promise<void> => {
  const expected = new Map(files.map((file) => [file.name, file.content]));
  const visit = async (directory: string, relative: string): Promise<void> => {
    const stat = await fs.lstat(directory);
    if (!stat.isDirectory() || stat.isSymbolicLink())
      throw new Error('Reference tree contains an unsafe directory');
    for (const entry of await fs.readdir(directory, { withFileTypes: true })) {
      const name = relative ? `${relative}/${entry.name}` : entry.name;
      const location = path.join(directory, entry.name);
      if (entry.isDirectory()) {
        if (![...expected.keys()].some((file) => file.startsWith(`${name}/`)))
          throw new Error('Reference tree contains an unexpected directory');
        await visit(location, name);
      } else {
        const content = expected.get(name);
        const metadata = await fs.lstat(location);
        if (
          content === undefined ||
          !metadata.isFile() ||
          metadata.isSymbolicLink() ||
          metadata.nlink !== 1 ||
          metadata.size !== Buffer.byteLength(content)
        )
          throw new Error(
            'Reference tree contains a missing, changed, or unsafe file',
          );
        if (!(await fs.readFile(location)).equals(Buffer.from(content)))
          throw new Error(
            'Reference file content does not match its saved version',
          );
        expected.delete(name);
      }
    }
  };
  await visit(root, '');
  if (expected.size)
    throw new Error('Reference tree is missing retained files');
};

export const materializeTextFiles = async (args: {
  files: Array<{ name: string; content: string }>;
  directory: string;
}): Promise<string> => {
  const { directory } = args;
  await fs.mkdir(directory, { recursive: true, mode: 0o700 });
  await ensureDirectory(directory);
  const files = [...args.files].sort((first, second) =>
    first.name < second.name ? -1 : Number(first.name > second.name),
  );
  const treeDigest = digest(
    JSON.stringify(files.map(({ name, content }) => [name, content])),
  );
  const destination = path.join(directory, treeDigest);
  const exists = await fs
    .lstat(destination)
    .then(() => true)
    .catch((error: NodeJS.ErrnoException) => {
      if (error.code !== 'ENOENT') throw error;
      return false;
    });
  if (!exists) {
    const staging = path.join(directory, `.${treeDigest}.${randomUUID()}`);
    await fs.mkdir(staging, { mode: 0o700 });
    try {
      for (const file of files) {
        const location = path.join(staging, file.name);
        await fs.mkdir(path.dirname(location), {
          recursive: true,
          mode: 0o700,
        });
        await fs.writeFile(location, file.content, { flag: 'wx', mode: 0o600 });
      }
      await fs
        .rename(staging, destination)
        .catch((error: NodeJS.ErrnoException) => {
          if (!['EEXIST', 'ENOTEMPTY'].includes(error.code ?? '')) throw error;
        });
    } finally {
      await fs.rm(staging, { recursive: true, force: true });
    }
  }
  await validateTree(destination, files);
  return destination;
};
